import pytest
from bug1 import numbers

def test_numbers_functionality():
    # Get the list of functions generated by numbers()
    funcs = numbers()
    
    # Test index 0: Should return x + 0
    assert funcs[0](10) == 10
    
    # Test index 1: Should return x + 1
    assert funcs[1](10) == 11
    
    # Test index 2: Should return x + 2
    assert funcs[2](10) == 12
    
    # Test a mid-range index (e.g., i=5)
    assert funcs[5](100) == 105
    
    # Test the last index (i=9)
    assert funcs[9](1) == 10